const LOGOS: ComponentType[] = [
  PowertutorsLogo,
  EducationBoutiqueLogo,
  OppidanLogo,
  LatimerTuitionLogo,
  DTPLogo,
  AthenaLogo,
  IvyLogo,
  SunsShineLogo,
  BonasLogo,
  GabbitasLogo,
  Quintessentially,
  TeliosLogo,
  StudyShackLogo,
];

const STEP_MS = 2000;
const FLIP_MS = 600;
const VISIBLE_SLOTS = 5;

type SlotState = {
  current: number;
  next: number;
  flipping: boolean;
};

interface CustomerLogosProps {
  heading?: string;
}

export const CustomerLogos = ({
  heading = "Designed for companies of all sizes, from entrepreneurs to enterprise, agencies, centers & online tutoring",
}: CustomerLogosProps) => {
  const [slots, setSlots] = useState<SlotState[]>(() =>
    Array.from({ length: VISIBLE_SLOTS }, (_, i) => ({
      current: i % LOGOS.length,
      next: (i + VISIBLE_SLOTS) % LOGOS.length,
      flipping: false,
    })),
  );
  const [activeSlot, setActiveSlot] = useState(0);

  useEffect(() => {
    setSlots((prev) => {
      const out = [...prev];
      out[activeSlot] = { ...out[activeSlot], flipping: true };
      return out;
    });

    const finishFlip = window.setTimeout(() => {
      setSlots((prev) => {
        const out = [...prev];
        const s = out[activeSlot];
        out[activeSlot] = {
          current: s.next,
          next: (s.next + VISIBLE_SLOTS) % LOGOS.length,
          flipping: false,
        };
        return out;
      });
    }, FLIP_MS);

    const advanceSlot = window.setTimeout(() => {
      setActiveSlot((i) => (i + 1) % VISIBLE_SLOTS);
    }, STEP_MS);

    return () => {
      window.clearTimeout(finishFlip);
      window.clearTimeout(advanceSlot);
    };
  }, [activeSlot]);

  return (
    <Body
      heading={
        <Heading variant="h2" size="xsmall" center>
          {heading}
        </Heading>
      }
    >
      <div className={styles.logos}>
        {slots.map((slot, i) => {
          const CurrentLogo = LOGOS[slot.current];
          const NextLogo = LOGOS[slot.next];
          return (
            <div key={i} className={styles.slot} data-index={i}>
              <div
                className={`${styles.track} ${slot.flipping ? styles.flipping : ""}`}
              >
                <div className={styles.face}>
                  <CurrentLogo />
                </div>
                <div className={styles.face}>
                  <NextLogo />
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </Body>
  );
};
